const executionId = String($execution.id ?? Date.now())
  .replace(/[^A-Za-z0-9_-]/g, '-');
const runToken = `${executionId}-${Date.now()}`;

return [
  {
    json: {
      workflow: 'NEXUS-N8N-WORKFLOW-007-EVENT-LEDGER-ORCHESTRATION',
      execution_id: executionId,
      run_token: runToken,
      event_name: 'n8n Workflow 007 Event Ledger Orchestration Verification',
      event_type: 'SYNC_CONFIRMED',
      state: 'VERIFIED',
      source_system: 'N8N',
      source_record_id: `NEXUS-N8N-WORKFLOW-007-${runToken}`,
      actor_type: 'N8N',
      actor_id: 'nexus_n8n_runtime',
      outcome_status: 'VERIFIED',
      idempotency_key: `NEXUS-N8N-WORKFLOW-007-${runToken}`,
      prepared_at: new Date().toISOString()
    }
  }
];

const prepared = $('Prepare Event Payload').first().json;
const recorded = $('Record Nexus Event').first().json;
const readback = $input.first().json;

if (!recorded?.event_id) {
  throw new Error('Workflow 007 failed: record gateway returned no event_id.');
}

if (!readback?.event_id) {
  throw new Error('Workflow 007 failed: governed readback returned no event.');
}

if (String(recorded.event_id) !== String(readback.event_id)) {
  throw new Error(
    `Workflow 007 failed: recorded event_id ${recorded.event_id} does not match readback event_id ${readback.event_id}.`
  );
}

const checks = {
  event_name: readback.event_name === prepared.event_name,
  event_type: readback.event_type === prepared.event_type,
  state: readback.state === prepared.state,
  source_system: readback.source_system === prepared.source_system,
  source_record_id: readback.source_record_id === prepared.source_record_id,
  actor_type: readback.actor_type === prepared.actor_type,
  actor_id: readback.actor_id === prepared.actor_id,
  outcome_status: readback.outcome_status === prepared.outcome_status,
  idempotency_key: readback.idempotency_key === prepared.idempotency_key,
  timestamp_present: Boolean(readback.event_timestamp),
  correlation_id_present: Boolean(readback.correlation_id)
};

const failedChecks = Object.entries(checks)
  .filter(([, passed]) => !passed)
  .map(([name]) => name);

if (failedChecks.length > 0) {
  throw new Error(
    `Workflow 007 failed readback verification: ${failedChecks.join(', ')}`
  );
}

return [
  {
    json: {
      ...prepared,
      first_event_id: recorded.event_id,
      readback_event_id: readback.event_id,
      event_timestamp: readback.event_timestamp,
      correlation_id: readback.correlation_id,
      readback_verified: true,
      readback_checks: checks
    }
  }
];

const prepared = $('Prepare Event Payload').first().json;
const readback = $('Verify Readback').first().json;
const replay = $input.first().json;

if (!replay?.event_id) {
  throw new Error('Workflow 007 failed: replay gateway returned no event_id.');
}

if (String(replay.event_id) !== String(readback.first_event_id)) {
  throw new Error(
    `Workflow 007 failed: replay event_id ${replay.event_id} does not match original event_id ${readback.first_event_id}.`
  );
}

if (replay.idempotency_key !== prepared.idempotency_key) {
  throw new Error('Workflow 007 failed: replay returned an unexpected idempotency key.');
}

return [
  {
    json: {
      workflow: prepared.workflow,
      mission: 'Governed Nexus event record, readback, payload verification, and idempotent replay',
      status: 'VERIFIED',
      execution_id: prepared.execution_id,
      receipt_timestamp: new Date().toISOString(),
      first_event_id: readback.first_event_id,
      readback_event_id: readback.readback_event_id,
      replay_event_id: replay.event_id,
      readback_verified: readback.readback_verified,
      idempotency_verified:
        String(replay.event_id) === String(readback.first_event_id),
      event_timestamp: readback.event_timestamp,
      correlation_id: readback.correlation_id,
      event_name: prepared.event_name,
      event_type: prepared.event_type,
      state: prepared.state,
      source_system: prepared.source_system,
      source_record_id: prepared.source_record_id,
      actor_type: prepared.actor_type,
      actor_id: prepared.actor_id,
      outcome_status: prepared.outcome_status,
      idempotency_key: prepared.idempotency_key,
      direct_table_access_used: false,
      gateway_record_used: true,
      gateway_read_used: true,
      next_action: 'Captain verifies the Workflow 007 receipt, then proceeds to Tracker-shaped event integration.'
    }
  }
];
